"""Concise local HTML; model images remain ignored and are referenced, never embedded."""
from pathlib import Path
import json,xml.etree.ElementTree as ET
ROOT=Path(__file__).resolve().parents[1];BASE=ROOT/'Docs/Design/MovementControlV1'
def main():
 r=json.loads((BASE/'verification.json').read_text(encoding='utf-8'))
 assert r['status']=='PASSED' and r['visual_review']['inspected_image_sha256']==r['images']
 tests=ET.parse(BASE/'runtime-local/tests/route.trx').find('.//{*}Counters').attrib
 assert tests['failed']=='0' and tests['passed']==tests['total']
 checks=sum(map(len,r['checks'].values()))
 html='''<!doctype html><html lang="ja"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>百代鏡 — 移動中の命令変更・取消</title>
<style>:root{color-scheme:dark;font:17px/1.8 "Yu Gothic UI",Meiryo,sans-serif;background:#101a22;color:#e9e9df}body{max-width:1080px;margin:auto;padding:32px 20px}h1{font-size:clamp(27px,4vw,40px);line-height:1.4}h2{font-size:24px;color:#dfc38d;margin-top:34px}a{color:#9ed8e7}section,.metric{background:#1c2a34;border:1px solid #394c58;border-radius:10px;padding:20px}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.metric strong{display:block;font-size:31px;color:#a8dfbf}table{border-collapse:collapse;width:100%}td,th{padding:10px;text-align:left;border-bottom:1px solid #40525d}.images{display:grid;grid-template-columns:1fr 1fr;gap:16px}figure{margin:0}img{display:block;width:100%;height:auto;border-radius:5px}figcaption,.muted{color:#afc2cb;font-size:14px}code{overflow-wrap:anywhere}.tag{color:#a8dfbf}.flow{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.flow span{background:#344b50;border-radius:7px;padding:12px}@media(max-width:650px){body{padding:20px 12px}.metrics,.images{grid-template-columns:1fr}td,th{padding:6px;font-size:14px}}</style>
<header><p class="tag">2026-10-20 / 実装・実Godot検証</p><h1>届いて、認識してから効く。<br>移動中の取消と行先変更。</h1><p>命令を送っただけで部隊を瞬間移動させず、伝令の受渡し・開封・効力時刻を分けました。取消は現在位置で停止し、帰城への変更は次の分岐から折り返します。</p></header>
<div class="metrics"><div class="metric"><strong>CORE_COUNT件</strong>全Core試験成功（新18件）</div><div class="metric"><strong>GPU_COUNT件</strong>実Godotの操作・復旧検査</div><div class="metric"><strong>16比較・0画素</strong>保存復旧と続行の3D描画差分</div></div>
<h2>受領と効力を分ける</h2><section><div class="flow"><span>5秒<br>発送</span>→<span>21秒<br>分岐点で受領</span>→<span>23秒<br>本人が開封</span>→<span>25秒<br>効力発生</span></div><p>既知の分岐点で伝令を渡します。相手の本当の現在位置を先読みして追跡しません。受渡し地点に本人がいなければ届かず、失敗報告にも配送時間がかかります。</p><p>重要命令の到達時は世界が停止。未開封の本文は表示せず、指定時刻を過ぎても開封前には適用しません。</p></section>
<h2>取消と変更の実画面</h2><div class="images"><figure><img src="runtime-local/cancel-effective.png" alt="25秒に東48mで停止した武将"><figcaption>取消：25秒、東48mで停止。その後もこの位置を保つ。</figcaption></figure><figure><img src="runtime-local/redirect-effective.png" alt="25秒に帰城への行程へ更新された武将"><figcaption>変更：同じ25秒・同じ位置で、帰城の行程に更新。</figcaption></figure><figure><img src="runtime-local/cancel-sealed.png" alt="21秒の未開封受領時の画面"><figcaption>21秒：届いていても、未開封の命令は本人の任務に出さない。</figcaption></figure><figure><img src="runtime-local/redirect-turn.png" alt="41秒に次の分岐から折り返す武将"><figcaption>41秒：現在区間を終えて折り返し、81秒に帰城する。</figcaption></figure></div>
<h2>4段階の保存を、両方の命令で復旧</h2><table><thead><tr><th>保存時点</th><th>復旧後に確認したこと</th></tr></thead><tbody><tr><td>20秒・発送中</td><td>まだ命令を知らず、伝令は21秒に到達する。</td></tr><tr><td>21秒・未開封</td><td>未開封のまま停止して復旧。開封前に適用しない。</td></tr><tr><td>24秒・効力待ち</td><td>元の移動を維持し、25秒に初めて制御を適用。</td></tr><tr><td>30秒・適用後</td><td>取消後の停止／変更後の行程と動作位相を保つ。</td></tr></tbody></table><p>取消と変更の各4保存を別Godotプロセスで読み直し、続行後の位置・経路・知識・最終返報まで確認しました。GPU原本29枚、復旧と続行の16比較で3D描画領域の差分0画素です。</p>
<div class="images"><figure><img src="runtime-local/cancel-applied.png" alt="取消適用後の保存前"><figcaption>取消適用後、30秒の保存前。</figcaption></figure><figure><img src="runtime-local/cancel-restored-applied.png" alt="同じ30秒へ別プロセスで復旧した画面"><figcaption>別プロセス復旧。同じ位置・向き・待機位相で停止。</figcaption></figure></div>
<h2>重複・遅着・競合も検査</h2><p>同じ命令IDの再入力、遅れた原本と正規再送分の同時到達でも、二重適用や移動の再始動が起きないことをCoreで確認しました。取消と行先変更の同時競合は、登録順を逆にしても取消を優先します。既に確定した過去の効果は巻き戻しません。</p>
<h2>起動と検証範囲</h2><p><code>Scripts/Show-MovementControl.ps1</code>で専用3D画面を開けます。移動を発送し、5秒程度で「取消を発送」または「帰城への変更を発送」。到達後に開封し、再開して確認できます。マウス操作ツール・カーソル設定変更は使っていません。</p><p>根拠：<a href="verification.json">ソース・DLL・素材・画像SHAと実測ログ</a> ／ <a href="../../Decisions/2026-10-20_MOVEMENT_CONTROL_V1.md">契約と限界</a>。画像・GLBはこのPC内のみで、Gitには追加していません。</p><p class="muted">検証用の既知の分岐点・徒歩・帰城変更まで。任意地点への追跡配送、使者自身の3D移動、任意の行先変更、騎馬の制動、全国地理、通常Mainへの新Core移行は未実施です。</p>
<h2>共有した最終形と、次の作業</h2><section><p><b>最終形は、日本全国に多数の城・集落・街道がある世界です。</b>全国と現地を同じ座標・世界時計でつなぎます。ここまでの小さな架空地図は、その基盤の検証です。</p><p><b>次は全国概略地図。</b><br>完了条件：日本の海岸線と主要城・拠点を置き、全国→地域→現地の表示を同じ座標でつなぐこと。全国すべての街道が完成するまで、地図を見せずに待つ計画にはしません。</p></section><footer><p class="muted">prototype/godot-foundation / main・design/foundationは変更していません。自己確認は新たなユーザー承認ではありません。</p></footer></html>'''.replace('CORE_COUNT',tests['passed']).replace('GPU_COUNT',str(checks))
 (BASE/'report.html').write_bytes(html.encode('utf-8'))
 print('Built movement-control report')
if __name__=='__main__':main()
